-- NeracaTugas 006: templat JK diselaraskan dengan MySG (kod JR/JM), bidang tugas, JK bersyarat.
-- DIJANA oleh scripts/jana-templat.mjs — jangan sunting tangan.

alter table public.jawatankuasa add column if not exists kod text;

create or replace function public._templat(p_jenis text)
returns jsonb language sql immutable set search_path = public as $fn$
select case when p_jenis = 'SK' then $j${"bidang":[{"nama":"Pentadbiran","warna":"indigo","jk":[{"kod":"JR01","nama":"JK Pengurusan Sekolah","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":true,"slot":[["Pengerusi",1],["Naib Pengerusi",1],["Setiausaha",1],["AJK",4]],"bidang_tugas":"Menetapkan hala tuju, dasar dan perancangan strategik sekolah.\nMenyelaras takwim sekolah dan penyediaan Buku Pengurusan.\nMerancang program kecemerlangan dan memantau prestasi sekolah (termasuk penilaian kendiri).\nMengurus penyelenggaraan fizikal, bilik khas, majlis rasmi dan perhubungan luar.\nMemantau kontrak keselamatan & kebersihan serta dokumentasi laporan sekolah.\nBermesyuarat sekurang-kurangnya 2 kali setahun (dipengerusikan PGB)."},{"kod":"JR02","nama":"JK Pengurusan Maklumat Sekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Mengurus pengumpulan, pengemaskinian dan kesahihan data sekolah (EMIS/APDM/IDME).\nMemastikan data dihantar kepada PPD/JPN/KPM mengikut tarikh ditetapkan.\nMenyimpan dokumen data dengan selamat dan menyelenggara peralatan data.\nMelaporkan kerosakan peralatan/talian kepada pihak berkenaan."},{"kod":"JR03","nama":"JK Pengurusan Sumber Manusia","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Mengurus perjawatan dan Anggaran Belanja Mengurus (ABM) perjawatan.\nMenyelaras penilaian prestasi, kenaikan pangkat dan rekod HRMIS.\nMerancang latihan profesional (LDP/PLC) dan program guru baharu.\nMengurus kebajikan, kesejahteraan dan isu staf bermasalah mengikut prosedur."},{"kod":"JR04","nama":"JK Pengurusan Kewangan, Akaun dan Aset Sekolah","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Merancang dan memantau agihan bajet serta perbelanjaan sekolah.\nMemastikan perolehan, terimaan dan bayaran mematuhi tatacara kewangan.\nMengurus rekod akaun, penyata dan audit dalaman.\nMengurus aset alih kerajaan: penerimaan, pendaftaran, pemeriksaan dan pelupusan."},{"kod":"JR05","nama":"JK Standard Kualiti Pendidikan Malaysia (SKPM)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Menyelaras penilaian kendiri sekolah berdasarkan SKPM.\nMengumpul eviden dan menganalisis dapatan setiap standard.\nMerancang tindakan penambahbaikan berdasarkan dapatan.\nMelapor pencapaian SKPM kepada pentadbir dan PPD."},{"kod":"JR06","nama":"JK Pendidikan Khas Sekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Merancang dan mengurus program pendidikan khas/integrasi/inklusif.\nMenyediakan Rancangan Pendidikan Individu (RPI) murid berkeperluan khas.\nMenyelaras penempatan, kemudahan dan bantuan murid berkeperluan khas.\nBerhubung dengan ibu bapa dan agensi berkaitan.","syarat":"ppki"},{"kod":"JR07","nama":"JK Pengurusan Prasekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Mengurus pendaftaran dan pemilihan murid prasekolah.\nMemastikan pelaksanaan kurikulum prasekolah kebangsaan.\nMenyelaras RMT/makanan, keselamatan dan kebajikan murid prasekolah.\nMelapor perkembangan murid kepada ibu bapa.","syarat":"prasekolah"},{"kod":"JR08","nama":"JK Pengurusan Bencana Sekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Menyediakan pelan tindakan kecemasan dan bencana sekolah.\nMelaksanakan latihan kebakaran/pengungsian sekurang-kurangnya sekali setahun.\nMenyenggara peralatan keselamatan dan laluan kecemasan.\nMenyelaras tindakan semasa bencana bersama agensi berkaitan."},{"kod":"JR09","nama":"JK Persatuan Ibu Bapa dan Guru (PIBG)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Menyelaras mesyuarat agung dan mesyuarat AJK PIBG.\nMerancang program kerjasama sekolah dan ibu bapa.\nMengurus kutipan dan penggunaan sumbangan PIBG secara telus.\nMematuhi peraturan PIBG yang berkuat kuasa."},{"kod":"JR10","nama":"JK Kelab Kebajikan Guru dan Kakitangan","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Mengurus kebajikan guru dan kakitangan (ziarah, sumbangan, penghargaan).\nMenganjurkan aktiviti kesejahteraan dan sambutan warga sekolah.\nMengurus yuran dan kewangan kelab dengan telus."},{"kod":"JR11","nama":"JK Pengurusan Murid Orang Asal","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Memantau kehadiran dan mencegah keciciran murid Orang Asal.\nMenyelaras bantuan, asrama dan program khas murid Orang Asal.\nBerhubung dengan keluarga dan agensi berkaitan.","syarat":"orang_asal"}]},{"nama":"Kurikulum","warna":"sky","jk":[{"kod":"JR12","nama":"JK Pengurusan Kurikulum","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":true,"slot":[["Pengerusi",1],["Naib Pengerusi",1],["Setiausaha",1],["AJK",4]],"bidang_tugas":"Menentukan dan menyelaras dasar kurikulum sekolah selari dengan KPM/JPN.\nMenyelaras jadual waktu, agihan mata pelajaran dan guru ganti (relief).\nMemantau pelaksanaan PdP dan program peningkatan akademik.\nMengenal pasti isu kurikulum dan merancang tindakan susulan.\nBermesyuarat sekurang-kurangnya 2 kali setahun (dipengerusikan PGB)."},{"kod":"JR13","nama":"Panitia Bahasa Melayu","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["Setiausaha",1],["AJK",2]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia Bahasa Inggeris","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["Setiausaha",1],["AJK",2]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia Matematik","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["Setiausaha",1],["AJK",2]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia Sains","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["Setiausaha",1],["AJK",2]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia Pendidikan Islam & Bahasa Arab","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["Setiausaha",1],["AJK",2]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia Sejarah","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["AJK",1]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia RBT","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["AJK",1]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia PJPK","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["AJK",1]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR13","nama":"Panitia Pendidikan Seni & Muzik","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Ketua Panitia",1],["AJK",1]],"bidang_tugas":"Merancang rancangan tahunan mata pelajaran dan program panitia.\nMemastikan PdP mematuhi DSKP dan memantau kemajuan murid.\nMenyelaras bahan bantu mengajar, pencerapan dan perkongsian amalan terbaik.\nMenganalisis pencapaian dan merancang intervensi."},{"kod":"JR14","nama":"JK Pentaksiran","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Menyelaras pelaksanaan Pentaksiran Bilik Darjah (PBD) dan pelaporan.\nMengurus pentaksiran/peperiksaan dalaman dan analisis keputusan.\nMemastikan kerahsiaan dan keselamatan instrumen pentaksiran.\nMelapor tahap penguasaan murid kepada pentadbir dan ibu bapa."},{"kod":"JR15","nama":"JK Pusat Sumber Sekolah (PSS)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["Setiausaha",1],["AJK",2]],"bidang_tugas":"Mengurus perpustakaan, bahan sumber dan media pendidikan.\nMelaksanakan program galakan membaca (NILAM) dan literasi maklumat.\nMenyokong guru dengan sumber PdP dan teknologi pendidikan."}]},{"nama":"Hal Ehwal Murid","warna":"emerald","jk":[{"kod":"JR16","nama":"JK Pengurusan Hal Ehwal Murid","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":true,"slot":[["Pengerusi",1],["Naib Pengerusi",1],["Setiausaha",1],["AJK",4]],"bidang_tugas":"Mengurus pendaftaran, pertukaran dan pemberhentian murid.\nMenyelaras pengurusan kelas, guru kelas dan pembangunan sahsiah murid.\nMengurus bantuan & kebajikan murid (biasiswa, SPBT, RMT, insurans).\nMemantau kantin dan kesejahteraan murid.\nBermesyuarat sekurang-kurangnya 2 kali setahun (dipengerusikan PGB)."},{"kod":"JR17","nama":"JK Pengurusan Disiplin Murid","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Menggubal dan menguatkuasa peraturan sekolah.\nMengendali kes disiplin mengikut prosedur dan merekod dalam sistem (SSDM).\nMengurus lembaga pengawas dan program pencegahan salah laku/ponteng.\nBerhubung dengan ibu bapa dan agensi bagi kes berat."},{"kod":"JR18","nama":"JK Pengurusan 3K (Kebersihan, Kesihatan, Keselamatan)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Memastikan kebersihan persekitaran sekolah dan tandas.\nMelaksanakan program kesihatan murid (saringan, imunisasi, PROSTAR).\nMengenal pasti risiko keselamatan dan mengambil tindakan pembetulan.\nMerekod dan melapor insiden 3K."},{"kod":"JR19","nama":"JK Bimbingan dan Kaunseling","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Memberi perkhidmatan kaunseling individu dan kelompok.\nMelaksanakan program pembangunan sahsiah dan pencegahan.\nMenyelaras bimbingan kerjaya dan kemahiran belajar.\nMerekod sesi dan menjaga kerahsiaan klien."},{"kod":"JR20","nama":"JK Pengurusan Asrama","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["Warden",3]],"bidang_tugas":"Mengurus kemasukan dan penempatan murid asrama.\nMenyelaras tugas warden, jadual dan disiplin asrama.\nMemastikan makanan, kebersihan dan keselamatan asrama.","syarat":"asrama"},{"kod":"","nama":"JK Rancangan Makanan Tambahan (RMT)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Menyelaras senarai penerima dan pelaksanaan Rancangan Makanan Tambahan.\nMemantau kualiti makanan dan rekod harian."},{"kod":"","nama":"JK Skim Pinjaman Buku Teks (SPBT)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Mengurus pesanan, penerimaan, pinjaman dan pemulangan buku teks.\nMenyelenggara rekod dan stok SPBT."}]},{"nama":"Kokurikulum","warna":"amber","jk":[{"kod":"JR21","nama":"JK Pengurusan Kokurikulum","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":true,"slot":[["Pengerusi",1],["Naib Pengerusi",1],["Setiausaha",1],["AJK",4]],"bidang_tugas":"Menentukan dasar dan takwim kokurikulum sekolah.\nMenyelaras unit beruniform, kelab/persatuan dan sukan/permainan.\nMemastikan pentaksiran PAJSK direkod dan dilapor.\nMengurus penyertaan pertandingan dan keselamatan aktiviti.\nBermesyuarat sekurang-kurangnya 2 kali setahun (dipengerusikan PGB)."},{"kod":"JR22","nama":"JK Pembangunan Sukan Sekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Merancang program pembangunan sukan dan bakat murid.\nMenyelaras jurulatih, latihan dan penyertaan kejohanan.\nMelaksanakan dasar Satu Murid Satu Sukan."},{"kod":"JR23","nama":"JK Sukan Tahunan Sekolah","tahap":"Sokongan","tempoh":"Bermusim","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",4]],"bidang_tugas":"Merancang dan melaksanakan kejohanan sukan tahunan sekolah.\nMenyelaras rumah sukan, pegawai teknikal dan keputusan.\nMemastikan keselamatan, peralatan dan kelengkapan kejohanan."},{"kod":"","nama":"Rumah Sukan Merah","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Rumah Sukan Biru","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Rumah Sukan Hijau","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Rumah Sukan Kuning","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Unit Beruniform: Pengakap","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Guru Penasihat",1],["AJK",1]],"bidang_tugas":"Merancang aktiviti unit, perkhemahan dan kenaikan lencana.\nMerekod kehadiran dan penilaian PAJSK ahli."},{"kod":"","nama":"Unit Beruniform: Tunas Puteri / Puteri Islam","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Guru Penasihat",1],["AJK",1]],"bidang_tugas":"Merancang aktiviti unit, perkhemahan dan kenaikan lencana.\nMerekod kehadiran dan penilaian PAJSK ahli."},{"kod":"","nama":"Kelab Sains & Matematik","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Guru Penasihat",1],["AJK",1]],"bidang_tugas":"Merancang aktiviti kelab/persatuan sepanjang tahun.\nMerekod kehadiran dan penilaian PAJSK ahli."}]}]}$j$::jsonb
else $j${"bidang":[{"nama":"Pentadbiran","warna":"indigo","jk":[{"kod":"JM01","nama":"JK Pengurusan Sekolah","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":true,"slot":[["Pengerusi",1],["Naib Pengerusi",1],["Setiausaha",1],["AJK",4]],"bidang_tugas":"Menetapkan hala tuju, dasar dan perancangan strategik sekolah.\nMenyelaras takwim sekolah dan penyediaan Buku Pengurusan.\nMerancang program kecemerlangan dan memantau prestasi sekolah (termasuk penilaian kendiri).\nMengurus penyelenggaraan fizikal, bilik khas, majlis rasmi dan perhubungan luar.\nMemantau kontrak keselamatan & kebersihan serta dokumentasi laporan sekolah.\nBermesyuarat sekurang-kurangnya 2 kali setahun (dipengerusikan PGB)."},{"kod":"JM02","nama":"JK Pengurusan Maklumat Sekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Mengurus pengumpulan, pengemaskinian dan kesahihan data sekolah (EMIS/APDM/IDME).\nMemastikan data dihantar kepada PPD/JPN/KPM mengikut tarikh ditetapkan.\nMenyimpan dokumen data dengan selamat dan menyelenggara peralatan data.\nMelaporkan kerosakan peralatan/talian kepada pihak berkenaan."},{"kod":"JM03","nama":"JK Pengurusan Sumber Manusia","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Mengurus perjawatan dan Anggaran Belanja Mengurus (ABM) perjawatan.\nMenyelaras penilaian prestasi, kenaikan pangkat dan rekod HRMIS.\nMerancang latihan profesional (LDP/PLC) dan program guru baharu.\nMengurus kebajikan, kesejahteraan dan isu staf bermasalah mengikut prosedur."},{"kod":"JM04","nama":"JK Pengurusan Kewangan, Akaun dan Aset Sekolah","tahap":"Utama","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Merancang dan memantau agihan bajet serta perbelanjaan sekolah.\nMemastikan perolehan, terimaan dan bayaran mematuhi tatacara kewangan.\nMengurus rekod akaun, penyata dan audit dalaman.\nMengurus aset alih kerajaan: penerimaan, pendaftaran, pemeriksaan dan pelupusan."},{"kod":"JM05","nama":"JK Standard Kualiti Pendidikan Malaysia (SKPM)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Menyelaras penilaian kendiri sekolah berdasarkan SKPM.\nMengumpul eviden dan menganalisis dapatan setiap standard.\nMerancang tindakan penambahbaikan berdasarkan dapatan.\nMelapor pencapaian SKPM kepada pentadbir dan PPD."},{"kod":"JM06","nama":"JK Pendidikan Khas Sekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Penyelaras",1],["AJK",2]],"bidang_tugas":"Merancang dan mengurus program pendidikan khas/integrasi/inklusif.\nMenyediakan Rancangan Pendidikan Individu (RPI) murid berkeperluan khas.\nMenyelaras penempatan, kemudahan dan bantuan murid berkeperluan khas.\nBerhubung dengan ibu bapa dan agensi berkaitan.","syarat":"ppki"},{"kod":"JM07","nama":"JK Pengurusan Bencana Sekolah","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Menyediakan pelan tindakan kecemasan dan bencana sekolah.\nMelaksanakan latihan kebakaran/pengungsian sekurang-kurangnya sekali setahun.\nMenyenggara peralatan keselamatan dan laluan kecemasan.\nMenyelaras tindakan semasa bencana bersama agensi berkaitan."},{"kod":"JM08","nama":"JK Persatuan Ibu Bapa dan Guru (PIBG)","tahap":"Sokongan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Menyelaras mesyuarat agung dan mesyuarat AJK PIBG.\nMerancang program kerjasama sekolah dan ibu bapa.\nMengurus kutipan dan penggunaan sumbangan PIBG secara telus.\nMematuhi peraturan PIBG yang berkuat kuasa."},{"kod":"JM09","nama":"JK Kelab Kebajikan Guru dan Kakitangan","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Pengerusi",1],["Setiausaha",1],["AJK",3]],"bidang_tugas":"Mengurus kebajikan guru dan kakitangan