enasihat",1],["AJK",2]],"bidang_tugas":"Mengurus operasi koperasi sekolah mengikut peraturan koperasi.\nMelatih murid dalam keusahawanan dan pengurusan koperasi.\nMenyediakan penyata kewangan dan mesyuarat agung tahunan."},{"kod":"","nama":"Rumah Sukan Merah","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Rumah Sukan Biru","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Rumah Sukan Hijau","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Rumah Sukan Kuning","tahap":"Sampingan","tempoh":"Bermusim","wajib":false,"slot":[["Ketua Rumah",1],["AJK",2]],"bidang_tugas":"Mengurus ahli rumah, latihan dan penyertaan sukan tahunan.\nMenjaga kebajikan dan disiplin ahli rumah."},{"kod":"","nama":"Unit Beruniform: Kadet Remaja Sekolah","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Guru Penasihat",1],["AJK",1]],"bidang_tugas":"Merancang aktiviti unit, perkhemahan dan kenaikan lencana.\nMerekod kehadiran dan penilaian PAJSK ahli."},{"kod":"","nama":"Unit Beruniform: Pengakap","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Guru Penasihat",1],["AJK",1]],"bidang_tugas":"Merancang aktiviti unit, perkhemahan dan kenaikan lencana.\nMerekod kehadiran dan penilaian PAJSK ahli."},{"kod":"","nama":"Kelab & Persatuan: Persatuan Bahasa Melayu","tahap":"Sampingan","tempoh":"Sepanjang tahun","wajib":false,"slot":[["Guru Penasihat",1],["AJK",1]],"bidang_tugas":"Merancang aktiviti kelab/persatuan sepanjang tahun.\nMerekod kehadiran dan penilaian PAJSK ahli."}]}]}$j$::jsonb end
